"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50153"],{69533(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.referenciada_por_exigencia_viva","status":422,"titulo":"A fase removida do cronograma \xe9 usada por um documento de outra fase como \xe2ncora de idade m\xe1xima"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.referenciada_por_exigencia_viva","requisitos":[],"oQueAconteceu":["O documento exigido pode limitar a idade de emiss\xe3o do comprovante contando a\\npartir do in\xedcio ou do fim de uma fase do cronograma, a refer\xeancia da idade m\xe1xima. A\\ndefini\xe7\xe3o do cronograma retira uma fase que \xe9 a refer\xeancia desse limite para um\\ndocumento exigido em **outra** fase que continua no cronograma. Sem a fase, a\\nidade m\xe1xima do documento ficaria sem refer\xeancia. A mensagem traz o c\xf3digo e a\\nordem da fase removida e o nome do documento.","O documento exigido na pr\xf3pria fase removida n\xe3o conta: ele sai junto com a fase.\\nS\xf3 o documento de uma fase que continua impede a remo\xe7\xe3o. A confer\xeancia \xe9 feita\\nfase por fase, na ordem em que o processo as tem, e para na primeira recusa; para\\numa fase removida, esta vem antes da recusa por etapa referenciada\\n([`etapa_da_fase_referenciada`](/erros/uniplus.selecao.fase_cronograma.etapa_da_fase_referenciada))\\ne da recusa por formul\xe1rio respondido na fase\\n([`fase_referenciada_por_formulario`](/erros/uniplus.selecao.processo_seletivo.fase_referenciada_por_formulario)).\\nNada \xe9 gravado."],"comoResolver":["Mantenha a fase no cronograma. Se ela deve mesmo sair, ajuste antes a exig\xeancia\\nnomeada na mensagem (defini\xe7\xe3o de documentos exigidos), apontando a refer\xeancia da\\nidade m\xe1xima para outra fase ou retirando o limite, e repita a defini\xe7\xe3o do\\ncronograma."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);